package org.apache.commons.compress.archivers.tar;

import java.io.*;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class TarUtils_parseOctal_TriageGen0Test {

    @Test
    public void testParseOctal_Simple() {
        byte[] buffer = "0000123".getBytes();
        // 123 in octal is 1*64 + 2*8 + 3 = 64 + 16 + 3 = 83
        assertEquals(83L, TarUtils.parseOctal(buffer, 0, buffer.length));
    }

    @Test
    public void testParseOctal_WithLeadingZeros() {
        byte[] buffer = "000755".getBytes();
        // 755 octal = 7*64 + 5*8 + 5 = 448 + 40 + 5 = 493
        assertEquals(493L, TarUtils.parseOctal(buffer, 0, buffer.length));
    }

    @Test
    public void testParseOctal_WithLeadingSpaces() {
        byte[] buffer = "   00123".getBytes();
        assertEquals(83L, TarUtils.parseOctal(buffer, 0, buffer.length));
    }

    @Test
    public void testParseOctal_WithNullTerminator() {
        byte[] buffer = "000123\0".getBytes();
        assertEquals(83L, TarUtils.parseOctal(buffer, 0, buffer.length));
    }

    @Test
    public void testParseOctal_WithTrailingSpaceAfterDigits() {
        // The code: if (currentByte == ' ') { break; } after stillPadding is false
        byte[] buffer = "000123 ".getBytes();
        assertEquals(83L, TarUtils.parseOctal(buffer, 0, buffer.length));
    }

    @Test
    public void testParseOctal_WithSpaceInMiddle() {
        // If a space appears after we have already started parsing digits, it should break
        byte[] buffer = "0001 23".getBytes();
        assertEquals(8L, TarUtils.parseOctal(buffer, 0, buffer.length));
    }

    @Test
    public void testParseOctal_AllZerosOrSpaces() {
        byte[] buffer = "00000".getBytes();
        assertEquals(0L, TarUtils.parseOctal(buffer, 0, buffer.length));

        byte[] buffer2 = "     ".getBytes();
        assertEquals(0L, TarUtils.parseOctal(buffer2, 0, buffer2.length));
    }

    @Test(expected = IllegalArgumentException.class)
    public void testParseOctal_InvalidDigit() {
        byte[] buffer = "00089".getBytes(); // 8 and 9 are not octal
        TarUtils.parseOctal(buffer, 0, buffer.length);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testParseOctal_InvalidChar() {
        byte[] buffer = "000A1".getBytes();
        TarUtils.parseOctal(buffer, 0, buffer.length);
    }

    @Test
    public void testParseOctal_OffsetAndLength() {
        byte[] buffer = "junk000123junk";
        // Start at index 4 ('0'), length 6 ('000123')
        assertEquals(83L, TarUtils.parseOctal(buffer, 4, 6));
    }

    @Test
    public void testParseOctal_EmptyBuffer() {
        byte[] buffer = new byte[0];
        assertEquals(0L, TarUtils.parseOctal(buffer, 0, 0));
    }

    @Test
    public void testParseOctal_LeadingSpaceThenDigit() {
        byte[] buffer = " 000123".getBytes();
        assertEquals(83L, TarUtils.parseOctal(buffer, 0, buffer.length));
    }

    @Test
    public void testParseOctal_SpaceOnly() {
        byte[] buffer = "   ".getBytes();
        assertEquals(0L, TarUtils.parseOctal(buffer, 0, buffer.length));
    }
}
